const body = $json.body ?? $json;
if (body.eventType !== 'candidate_application_submitted') throw new Error('Invalid candidate application event');
const roleId = String(body.Role_ID ?? body.roleId ?? '').trim();
const candidate = body.candidate ?? {};
if (!roleId || !String(candidate.name ?? '').trim() || !String(candidate.email ?? '').includes('@') || String(candidate.resumeText ?? '').trim().length < 20) throw new Error('Candidate application is incomplete');
return [{json:{'Application ID':body.applicationId ?? '', 'Candidate Name':candidate.name, Email:candidate.email, 'Contact Number':candidate.phone ?? '', Role_ID:roleId, 'Selected Role':body.jobTitle ?? '', 'Resume/CV':candidate.resumeText, 'Status (Resume Processing)':'Submitted', 'Date of Application':body.submittedAt ?? new Date().toISOString()}}];
